#!/usr/bin/env bash
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
OUT="$ROOT/build/recognition-eval-fixtures"
mkdir -p "$OUT"

# These are mechanics fixtures generated by macOS speech synthesis, never
# recordings of David or evidence of his recognition quality.
say -v Alex -r 190 -o "$OUT/shukuru-short.aiff" 'Shukuru.'
say -v Alex -r 190 -o "$OUT/shukuru-context.aiff" 'Please open the Shukuru project.'
say -v Alex -r 190 -o "$OUT/ordinary-short.aiff" 'Send the report.'

for path in "$OUT"/*.aiff; do
  audio_bytes="$(afinfo "$path" | awk '/audio bytes:/ {print $3}')"
  if [[ -z "$audio_bytes" || "$audio_bytes" -le 0 ]]; then
    echo "No audio frames produced for $path; check macOS speech service access" >&2
    exit 1
  fi
  afinfo "$path" | awk -v label="$path" '/estimated duration:/ {print label ": " $3 "s"}'
done

cat > "$OUT/dictionary.json" <<'JSON'
[{"preferredText":"Shukuru","aliases":["Shukaru"]}]
JSON
